<template><main class="auth-help"><section class="space-y-5"><h1 class="text-2xl font-bold">Nueva contraseña</h1><p>Usa entre 8 y 128 caracteres, con mayúscula, minúscula y número.</p><form v-if="!message" class="space-y-4" @submit.prevent="submit"><label class="block">Nueva contraseña<input v-model="password" class="operation-filter block w-full mt-2" type="password" autocomplete="new-password" minlength="8" maxlength="128" required :disabled="busy"></label><label class="block">Confirmar contraseña<input v-model="confirmation" class="operation-filter block w-full mt-2" type="password" autocomplete="new-password" required :disabled="busy"></label><CButton type="submit" :loading="busy">Guardar contraseña</CButton></form><p v-if="error" class="operation-error" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p><NuxtLink to="/auth/login" class="button-link">Iniciar sesión</NuxtLink></section></main></template>
<script setup lang="ts">
definePageMeta({layout:'auth',middleware:'auth'})
const config=useRuntimeConfig(),route=useRoute(),password=ref(''),confirmation=ref(''),busy=ref(false),message=ref(''),error=ref('')
useHead({meta:[{name:'referrer',content:'no-referrer'},{name:'robots',content:'noindex,nofollow'}]})
const submit=async()=>{error.value='';if(password.value!==confirmation.value){error.value='Las contraseñas no coinciden';return}busy.value=true;try{const r=await $fetch<{message:string}>(`${config.public.apiBase}/users/reset-password`,{method:'POST',body:{token:route.query.token,password:password.value},retry:0});message.value=r.message;password.value='';confirmation.value='';await navigateTo('/auth/reset-password',{replace:true})}catch(e){error.value=(e as {data?:{message?:string}}).data?.message||'No se pudo cambiar la contraseña'}finally{busy.value=false}}
</script>
